// Squads message wrapping percolator PushEwmaMark (tag 36). The market authority is the Squads
// vault, so even a test premium used for funding accrual goes through the same timelocked control path.
fn build_push_ewma_mark_message(
    squads_vault: &Pubkey,
    market: &Pubkey,
    perc: &Pubkey,
    now_slot: u64,
    mark_e6: u64,
) -> Vec<u8> {
    let mut m = Vec::new();
    m.push(1); // num_signers
    m.push(0); // num_writable_signers
    m.push(1); // num_writable_non_signers (market)
    m.push(3); // account_keys
    m.extend_from_slice(squads_vault.as_ref()); // 0 signer
    m.extend_from_slice(market.as_ref()); // 1 w
    m.extend_from_slice(perc.as_ref()); // 2 program
    m.push(1); // instructions
    m.push(2); // program_id_index -> percolator
    m.push(2); // account_indexes: oracle authority, market
    m.push(0);
    m.push(1);
    let data = percolator_prog::ix::Instruction::PushEwmaMark {
        asset_index: 0,
        now_slot,
        mark_e6,
    }
    .encode();
    m.extend_from_slice(&(data.len() as u16).to_le_bytes());
    m.extend_from_slice(&data);
    m.push(0);
    m
}

